pages['biology.html']=('Biology','Investigate life. Understand your world.','''<div class="with-sidebar"><aside data-section="department-contact" data-component="department-sidebar"><h2>Biology at Redbrook</h2><a href="#features">Department features</a><a href="#outcomes">Student outcomes</a><a href="#perspectives">Student perspectives</a><h3>Contact information</h3><p>Chair: Dr. Avery Linden<br>Coordinator: Morgan Vale<br>Science Hall, Room 204</p><p>Fictional department contact; use the local inquiry demonstration.</p><a href="admissions.html#inquiry">Ask about biology</a></aside><div><section id="features" data-section="department-features"><h2>Learn through investigation</h2><img class="wide" src="assets/fieldwork.svg" alt="Illustrated stream fieldwork landscape"><p>Build a foundation in ecology, genetics and cellular systems. In seminar, lab and field, practice turning an observation into a testable question.</p><h3>A sample path through the major</h3><ul><li>Foundations of living systems</li><li>Methods in biological investigation</li><li>Ecology and evolution</li><li>Senior research seminar</li></ul></section><section id="outcomes" data-section="student-outcomes"><h2>Where your questions can lead</h2><p>Practice scientific writing, research design and collaboration. These skills support further study and exploration of environmental, laboratory and education careers; no placement outcome is promised.</p></section><section id="perspectives" data-section="student-perspectives"><h2>From a notebook to a new question</h2><p>In this fictional student project, Rowan maps changes along a stream and shares a field guide with classmates.</p><h3>Alumni in action</h3><p>An illustrative graduate connects biology and public communication through community science workshops.</p><a href="news.html#stream">Department news: studying the stream →</a></section></div></div>''')
pages['admissions.html']=('Admissions','Start with a conversation. See where it takes you.', '''<section data-section="admissions-routes"><h2>Your next steps</h2>'''+cards([('Visit','Get a feel for the place','Explore campus scenes and prepare questions for your visit.','visit.html','Plan a visit'),('Connect','Tell us what interests you','Try a local information inquiry with fictional details.','#inquiry','Connect with us'),('Apply','Begin your next chapter','Review a sample application pathway and policies.','apply.html','Explore applying')])+'''</section><section class="band" data-section="why-redbrook"><h2>Why Redbrook?</h2><p>Make connections across subjects, learn through experience and find people who care about your questions. Our fictional community offers a window into a liberal-arts education.</p><a href="tuition-aid.html">Understand tuition and aid →</a></section>'''+inquiry())
pages['apply.html']=('Take the first step toward your future.','Application exploration • local demonstration only.', '''<section data-section="application-overview"><h2>Apply to Redbrook</h2><p>This research replica does not accept applications, documents, accounts or payments. Explore a sample checklist; no information leaves this page.</p><ol class="steps"><li>Learn about academic programs and campus life.</li><li>Prepare a personal statement and school records.</li><li>Discuss your timeline with a trusted adviser.</li></ol><a class="button" href="admissions.html#inquiry">Try an information inquiry</a></section><section data-section="application-timing"><h2>Which timeline fits you?</h2><p>Early decision is a commitment that deserves careful consideration. Review affordability and talk with your supporters before selecting any real application plan.</p><details data-component="policy-disclosure"><summary>Sample application materials</summary><p>Personal statement, transcript, school recommendation and a record of activities. This fictional list is illustrative and has no submission function.</p></details><details data-component="policy-disclosure"><summary>Campus policies</summary><p>This demo welcomes different learning paths. No real admissions, testing or accommodation policy is represented. Contact the actual institution for official requirements.</p></details></section>''')
pages['tuition-aid.html']=('An education worth exploring. A cost worth understanding.','Tuition and aid', '''<section data-section="aid-overview"><h2>Start with the whole picture</h2><p>Tuition is one part of a college budget. Compare living costs, books and personal expenses alongside grants and other assistance. All amounts below are fictional annual examples.</p><div class="with-sidebar"><div><h3>Illustrative cost of attendance</h3><table data-component="cost-table"><caption>Sample annual costs — not an offer or bill</caption><thead><tr><th scope="col">Expense</th><th scope="col">Example amount</th></tr></thead><tbody><tr><th scope="row">Tuition</th><td>$48,000</td></tr><tr><th scope="row">Housing and meals</th><td>$14,000</td></tr><tr><th scope="row">Books and personal expenses</th><td>$2,500</td></tr><tr><th scope="row">Total before assistance</th><td>$64,500</td></tr></tbody></table></div><aside class="callout" data-component="aid-guidance"><h3>Cost calculators</h3><p>Real calculators need personal financial information. This local replica provides no estimate of eligibility or award.</p><a href="admissions.html#inquiry">Try a sample assistance inquiry →</a></aside></div></section><section data-section="financial-assistance"><h2>Financial assistance</h2><h3>How to prepare</h3><p>Gather financial records, review deadlines and keep copies of submitted materials. Discuss grants, work opportunities and borrowing with an adviser.</p><h3>Request an early estimate</h3><p>The inquiry demonstration can show a confirmation message. It cannot calculate aid or contact an office.</p><h3>Questions about a bill?</h3><p>No payment or account access is available in this research sample.</p></section>''')
pages['visit.html']=('Visit Redbrook','Walk the paths. Picture the possibilities.', '''<section data-section="visit-opportunities"><h2>Find your way to campus</h2><p>Explore a sample campus visit: a student-led walk, a conversation about learning and time to discover the town. No real appointments or availability are offered.</p><div class="slideshow" data-component="visit-slideshow"><img id="visit-image" class="wide" src="assets/campus.svg" alt="Original illustration of a brick college hall beside green lawns"><p id="slide-caption" role="status">1 of 3 — The green: a meeting place at the center of campus.</p><div class="actions"><button id="previous-slide" type="button">← Previous scene</button><button id="next-slide" type="button">Next scene →</button></div></div></section><section data-section="visit-preparation"><h2>Make the most of your visit</h2><details data-component="visit-question"><summary>How should I prepare?</summary><p>Write down questions about classes, community and access. Wear comfortable shoes and check the weather before a real visit.</p></details><details data-component="visit-question"><summary>What should I do during a first visit?</summary><p>Talk with students, explore a classroom area and give yourself time to reflect on what you notice.</p></details><details data-component="visit-question"><summary>What might I see on a campus tour?</summary><p>A typical sample route includes the green, a science space and a gathering place. Actual tours may differ.</p></details><a class="button" href="admissions.html#inquiry">Try a visit inquiry</a></section>''')
